ArenaBlock* arenaNewBlock(size_t size);
void Arena_init(Arena* self, size_t size);
void* Arena_alloc(Arena* self, size_t size, size_t align);
void Arena_freeAll(Arena* self);

typedef struct ArenaBlock {
    uint8_t* data;
    size_t size;
    size_t used;
    ArenaBlock* next;
} ArenaBlock;

typedef struct Arena {
    ArenaBlock* head;
    size_t blockSize;
} Arena;

/* pub */ ArenaBlock* arenaNewBlock(size_t size) {
    ArenaBlock* b = ((ArenaBlock*)malloc(sizeof(ArenaBlock)));
    if ((b == NULL)) {
        return NULL;
    }
    (b->data = ((uint8_t*)malloc(size)));
    (b->size = size);
    (b->used = 0);
    (b->next = NULL);
    if ((b->data == NULL)) {
        free(((void*)b));
        return NULL;
    }
    return b;
}
void Arena_init(Arena* self, size_t size) {
    if ((size < 64)) {
        (size = 64);
    }
    (self->blockSize = size);
    (self->head = arenaNewBlock(size));
}
void* Arena_alloc(Arena* self, size_t size, size_t align) {
    if ((align == 0)) {
        (align = 1);
    }
    if ((self->head == NULL)) {
        (self->head = arenaNewBlock(self->blockSize));
    }
    ArenaBlock* b = self->head;
    if ((b == NULL)) {
        return NULL;
    }
    size_t used = (((b->used + align) - 1) & (~ (align - 1)));
    if (((used + size) > b->size)) {
        size_t newSize = self->blockSize;
        if ((((size + align) + align) > newSize)) {
            (newSize = ((size + align) + align));
        }
        ArenaBlock* nb = arenaNewBlock(newSize);
        if ((nb == NULL)) {
            return NULL;
        }
        (nb->next = b);
        (self->head = nb);
        (b = nb);
        (used = 0);
    }
    void* ptr = ((void*)(((size_t)b->data) + used));
    (b->used = (used + size));
    return ptr;
}
void Arena_freeAll(Arena* self) {
    ArenaBlock* b = self->head;
    while ((b != NULL)) {
        ArenaBlock* nxt = b->next;
        free(((void*)b->data));
        free(((void*)b));
        (b = nxt);
    }
    (self->head = arenaNewBlock(self->blockSize));
}



