Slice Slice_from(uint8_t* p, size_t len);
_Bool Slice_eq(Slice* self, Slice b);

typedef struct Slice {
    uint8_t* ptr;
    size_t len;
} Slice;

Slice Slice_from(uint8_t* p, size_t len) {
    return (Slice){.ptr = p, .len = len};
}
_Bool Slice_eq(Slice* self, Slice b) {
    if ((self->len != b.len)) {
        return 0;
    }
    for (size_t i = 0; (i < self->len); (i++)) {
        if ((self->ptr[i] != b.ptr[i])) {
            return 0;
        }
    }
    return 1;
}



