_Bool isIdentStart(uint8_t c);
_Bool isIdentCont(uint8_t c);
_Bool isDigit(uint8_t c);
Slice mkSlice(uint8_t* p, size_t n);
void CrlbLexer_init(CrlbLexer* self, Slice s);
uint8_t CrlbLexer_peek(CrlbLexer* self);
void CrlbLexer_skipWsAndComments(CrlbLexer* self);
uint8_t CrlbLexer_advance(CrlbLexer* self);
CrlbToken CrlbLexer_next(CrlbLexer* self);

typedef struct CrlbLexer {
    Slice src;
    size_t pos;
    size_t line;
    size_t col;
    _Bool hadError;
} CrlbLexer;

void CrlbLexer_init(CrlbLexer* self, Slice s) {
    (*self = (CrlbLexer){.src = s, .pos = 0, .line = 1, .col = 1, .hadError = 0});
}
uint8_t CrlbLexer_peek(CrlbLexer* self) {
    if ((self->pos >= self->src.len)) {
        return 0;
    }
    return self->src.ptr[self->pos];
}
void CrlbLexer_skipWsAndComments(CrlbLexer* self) {
    while (1) {
        uint8_t c = CrlbLexer_peek(self);
        if (((((c == ' ') || (c == '\t')) || (c == '\r')) || (c == '\n'))) {
            CrlbLexer_advance(self);
            continue;
        }
        if ((c == '#')) {
            while (((CrlbLexer_peek(self) != 0) && (CrlbLexer_peek(self) != '\n'))) {
                CrlbLexer_advance(self);
            }
            continue;
        }
        break;
    }
}
uint8_t CrlbLexer_advance(CrlbLexer* self) {
    uint8_t c = self->src.ptr[self->pos];
    (self->pos = (self->pos + 1));
    if ((c == '\n')) {
        (self->line = (self->line + 1));
        (self->col = 1);
    } else {
        {
            (self->col = (self->col + 1));
        }
    }
    return c;
}
CrlbToken CrlbLexer_next(CrlbLexer* self) {
    CrlbLexer_skipWsAndComments(self);
    CrlbToken t = (CrlbToken){.kind = CrlbTokenKind_Eof, .text = mkSlice(NULL, 0), .line = self->line, .col = self->col, .numValue = 0, .boolValue = 0};
    if ((self->pos >= self->src.len)) {
        return t;
    }
    uint8_t c = CrlbLexer_peek(self);
    if ((c == '{')) {
        CrlbLexer_advance(self);
        (t.kind = CrlbTokenKind_LBrace);
        return t;
    }
    if ((c == '}')) {
        CrlbLexer_advance(self);
        (t.kind = CrlbTokenKind_RBrace);
        return t;
    }
    if ((c == '[')) {
        CrlbLexer_advance(self);
        (t.kind = CrlbTokenKind_LBracket);
        return t;
    }
    if ((c == ']')) {
        CrlbLexer_advance(self);
        (t.kind = CrlbTokenKind_RBracket);
        return t;
    }
    if ((c == '=')) {
        CrlbLexer_advance(self);
        (t.kind = CrlbTokenKind_Equals);
        return t;
    }
    if ((c == ';')) {
        CrlbLexer_advance(self);
        (t.kind = CrlbTokenKind_Semi);
        return t;
    }
    if ((c == ',')) {
        CrlbLexer_advance(self);
        (t.kind = CrlbTokenKind_Comma);
        return t;
    }
    if ((c == '"')) {
        CrlbLexer_advance(self);
        size_t start = self->pos;
        size_t writePos = start;
        while (1) {
            uint8_t cc = CrlbLexer_peek(self);
            if ((cc == 0)) {
                (self->hadError = 1);
                (t.kind = CrlbTokenKind_Error);
                return t;
            }
            if ((cc == '"')) {
                CrlbLexer_advance(self);
                break;
            }
            if ((cc == '\\')) {
                CrlbLexer_advance(self);
                uint8_t esc = CrlbLexer_peek(self);
                if ((esc == 0)) {
                    (self->hadError = 1);
                    (t.kind = CrlbTokenKind_Error);
                    return t;
                }
                CrlbLexer_advance(self);
                uint8_t decoded;
                switch (esc) {
                    case 'n':
                    {
                        (decoded = '\n');
                        break;
                    }
                    case 't':
                    {
                        (decoded = '\t');
                        break;
                    }
                    case 'r':
                    {
                        (decoded = '\r');
                        break;
                    }
                    case '"':
                    {
                        (decoded = '"');
                        break;
                    }
                    case '\\':
                    {
                        (decoded = '\\');
                        break;
                    }
                    default:
                    {
                        (decoded = esc);
                        break;
                    }
                }
                (self->src.ptr[writePos] = decoded);
                (writePos = (writePos + 1));
                continue;
            }
            (self->src.ptr[writePos] = cc);
            (writePos = (writePos + 1));
            CrlbLexer_advance(self);
        }
        (t.kind = CrlbTokenKind_String);
        (t.text = mkSlice((self->src.ptr + start), (writePos - start)));
        return t;
    }
    if (isDigit(c)) {
        size_t start = self->pos;
        while (isDigit(CrlbLexer_peek(self))) {
            CrlbLexer_advance(self);
        }
        size_t l = (self->pos - start);
        (t.kind = CrlbTokenKind_Number);
        (t.text = mkSlice((self->src.ptr + start), l));
        int64_t v = 0;
        size_t i = 0;
        while ((i < l)) {
            (v = ((v * 10) + ((int64_t)(self->src.ptr[(start + i)] - '0'))));
            (i = (i + 1));
        }
        (t.numValue = v);
        return t;
    }
    if (isIdentStart(c)) {
        size_t start = self->pos;
        while (isIdentCont(CrlbLexer_peek(self))) {
            CrlbLexer_advance(self);
        }
        size_t l = (self->pos - start);
        Slice txt = mkSlice((self->src.ptr + start), l);
        if (Slice_eq(&txt, mkSlice("true", 4))) {
            (t.kind = CrlbTokenKind_Bool);
            (t.boolValue = 1);
            (t.text = txt);
            return t;
        }
        if (Slice_eq(&txt, mkSlice("false", 5))) {
            (t.kind = CrlbTokenKind_Bool);
            (t.boolValue = 0);
            (t.text = txt);
            return t;
        }
        (t.kind = CrlbTokenKind_Ident);
        (t.text = txt);
        return t;
    }
    CrlbLexer_advance(self);
    (self->hadError = 1);
    (t.kind = CrlbTokenKind_Error);
    (t.text = mkSlice((self->src.ptr + (self->pos - 1)), 1));
    return t;
}
/* pub */ _Bool isIdentStart(uint8_t c) {
    return ((((c >= 'A') && (c <= 'Z')) || ((c >= 'a') && (c <= 'z'))) || (c == '_'));
}
/* pub */ _Bool isIdentCont(uint8_t c) {
    if (isIdentStart(c)) {
        return 1;
    }
    return (((c >= '0') && (c <= '9')) || (c == '-'));
}
/* pub */ _Bool isDigit(uint8_t c) {
    return ((c >= '0') && (c <= '9'));
}
/* pub */ Slice mkSlice(uint8_t* p, size_t n) {
    Slice s;
    (s.ptr = p);
    (s.len = n);
    return s;
}



