/* pub */ void valueArrayPush(ValueArray* arr, Value v) {
    if ((arr->len >= arr->cap)) {
        size_t newCap = 8;
        if ((arr->cap != 0)) {
            (newCap = (arr->cap * 2));
        }
        Value* fresh = ((Value*)Arena_alloc(arr->arena, (newCap * sizeof(Value)), 8));
        if ((fresh == NULL)) {
            return;
        }
        size_t i = 0;
        while ((i < arr->len)) {
            (fresh[i] = arr->data[i]);
            (i = (i + 1));
        }
        (arr->data = fresh);
        (arr->cap = newCap);
    }
    (arr->data[arr->len] = v);
    (arr->len = (arr->len + 1));
}



