Token Lexer_lexString(Lexer* self, uint8_t* start);
Token Lexer_lexCString(Lexer* self, uint8_t* start);
Token Lexer_lexRawString(Lexer* self, uint8_t* start);

Token Lexer_lexString(Lexer* self, uint8_t* start) {
    while ((! Lexer_isAtEnd(self))) {
        uint8_t c = self->cur[0];
        if ((c == '\"')) {
            (self->cur++);
            return Lexer_makeToken(self, TokenKind_String, start);
        }
        if ((c == '\\')) {
            EscapeResult esc = EscapeResult_decodeEscapeSequence(self->cur, self->bufEnd);
            if ((! esc.isValid)) {
                Lexer_reportErrorCode(self, ErrorCode_LexInvalidEscape, self->bufStart, self->bufEnd, self->cur, "invalid escape sequence");
            }
            if ((esc.bytesConsumed == 0)) {
                (self->cur++);
            } else {
                (self->cur += esc.bytesConsumed);
            }
            continue;
        }
        if ((c == '\n')) {
            (self->line++);
            (self->lineStart = (self->cur + 1));
        }
        (self->cur++);
    }
    Lexer_reportErrorCode(self, ErrorCode_LexUnterminatedString, self->bufStart, self->bufEnd, start, "unterminated string literal");
    return Lexer_makeToken(self, TokenKind_String, start);
}
Token Lexer_lexCString(Lexer* self, uint8_t* start) {
    while ((! Lexer_isAtEnd(self))) {
        uint8_t c = self->cur[0];
        if ((c == '\"')) {
            (self->cur++);
            return Lexer_makeToken(self, TokenKind_CString, start);
        }
        if ((c == '\\')) {
            EscapeResult esc = EscapeResult_decodeEscapeSequence(self->cur, self->bufEnd);
            if ((! esc.isValid)) {
                Lexer_reportErrorCode(self, ErrorCode_LexInvalidEscape, self->bufStart, self->bufEnd, self->cur, "invalid escape sequence");
            }
            if ((esc.bytesConsumed == 0)) {
                (self->cur++);
            } else {
                (self->cur += esc.bytesConsumed);
            }
            continue;
        }
        if ((c == '\n')) {
            (self->line++);
            (self->lineStart = (self->cur + 1));
        }
        (self->cur++);
    }
    Lexer_reportErrorCode(self, ErrorCode_LexUnterminatedString, self->bufStart, self->bufEnd, start, "unterminated C string literal");
    return Lexer_makeToken(self, TokenKind_CString, start);
}
Token Lexer_lexRawString(Lexer* self, uint8_t* start) {
    if ((Lexer_isAtEnd(self) || (self->cur[0] != '"'))) {
        Lexer_reportErrorCode(self, ErrorCode_LexUnterminatedString, self->bufStart, self->bufEnd, start, "expected '\"' after R for raw string");
        return Lexer_makeToken(self, TokenKind_RawString, start);
    }
    (self->cur++);
    uint8_t* delimStart = self->cur;
    while (((! Lexer_isAtEnd(self)) && (self->cur[0] != '('))) {
        (self->cur++);
    }
    size_t delimLen = ((size_t)(self->cur - delimStart));
    if ((Lexer_isAtEnd(self) || (self->cur[0] != '('))) {
        Lexer_reportErrorCode(self, ErrorCode_LexUnterminatedString, self->bufStart, self->bufEnd, start, "expected '(' in raw string delimiter");
        return Lexer_makeToken(self, TokenKind_RawString, start);
    }
    (self->cur++);
    while ((! Lexer_isAtEnd(self))) {
        uint8_t c = self->cur[0];
        if ((c == '\n')) {
            (self->line++);
            (self->lineStart = (self->cur + 1));
        }
        if ((c == ')')) {
            _Bool match = 1;
            for (size_t i = 0; (i < delimLen); (i++)) {
                size_t idx = ((size_t)(((self->cur + 1) + i) - self->bufStart));
                if ((idx >= ((size_t)(self->bufEnd - self->bufStart)))) {
                    (match = 0);
                    break;
                }
                if ((self->bufStart[idx] != delimStart[i])) {
                    (match = 0);
                    break;
                }
            }
            if (match) {
                size_t quoteIdx = ((size_t)(((self->cur + 1) + delimLen) - self->bufStart));
                if (((quoteIdx < ((size_t)(self->bufEnd - self->bufStart))) && (self->bufStart[quoteIdx] == '"'))) {
                    (self->cur = ((uint8_t*)((self->bufStart + quoteIdx) + 1)));
                    return Lexer_makeToken(self, TokenKind_RawString, start);
                }
            }
        }
        (self->cur++);
    }
    Lexer_reportErrorCode(self, ErrorCode_LexUnterminatedString, self->bufStart, self->bufEnd, start, "unterminated raw string literal");
    return Lexer_makeToken(self, TokenKind_RawString, start);
}



