Token Lexer_nextToken(Lexer* self);

Token Lexer_nextToken(Lexer* self) {
    if (Lexer_isAtEnd(self)) {
        return Lexer_makeToken(self, TokenKind_Eof, self->cur);
    }
    Lexer_skipWsCmts(self);
    uint8_t* start = self->cur;
    if (Lexer_isAtEnd(self)) {
        return Lexer_makeToken(self, TokenKind_Eof, start);
    }
    uint8_t c = self->cur[0];
    (self->cur++);
    if ((((c == 'R') && (! Lexer_isAtEnd(self))) && (self->cur[0] == '"'))) {
        (self->cur++);
        return Lexer_lexRawString(self, start);
    }
    if ((((c == 'C') && (! Lexer_isAtEnd(self))) && (self->cur[0] == '"'))) {
        (self->cur++);
        return Lexer_lexCString(self, start);
    }
    if ((((((c == 'u') || (c == 'U')) || (c == 'c')) && (! Lexer_isAtEnd(self))) && (self->cur[0] == '"'))) {
        (self->cur++);
        return Lexer_lexString(self, start);
    }
    if ((((((c == 'u') && (! Lexer_isAtEnd(self))) && (self->cur[0] == '8')) && ((self->cur + 1) < self->bufEnd)) && (self->cur[1] == '"'))) {
        (self->cur += 2);
        return Lexer_lexString(self, start);
    }
    if (((((c | 32) >= 'a') && ((c | 32) <= 'z')) || (c == '_'))) {
        return Lexer_lexIdentifier(self, start);
    }
    if (((c >= 192) && (c <= 253))) {
        size_t len;
        uint32_t cp = decodeUtf8(start, self->bufEnd, (& len));
        if (((len > 0) && isXidStart(cp))) {
            (self->cur = (start + len));
            return Lexer_lexIdentifier(self, start);
        }
    }
    if (((c >= '0') && (c <= '9'))) {
        return Lexer_lexNumber(self, start);
    }
    if ((c == '"')) {
        return Lexer_lexString(self, start);
    }
    if ((c == '\'')) {
        _Bool terminated = 0;
        while ((! Lexer_isAtEnd(self))) {
            if ((self->cur[0] == '\'')) {
                (self->cur++);
                (terminated = 1);
                break;
            }
            if ((self->cur[0] == '\n')) {
                break;
            }
            if ((self->cur[0] == '\\')) {
                EscapeResult esc = EscapeResult_decodeEscapeSequence(self->cur, self->bufEnd);
                if ((! esc.isValid)) {
                    Lexer_reportErrorCode(self, ErrorCode_LexInvalidEscape, self->bufStart, self->bufEnd, self->cur, "invalid escape sequence");
                }
                if ((esc.bytesConsumed == 0)) {
                    (self->cur++);
                } else {
                    (self->cur += esc.bytesConsumed);
                }
            } else {
                {
                    size_t len;
                    decodeUtf8(self->cur, self->bufEnd, (& len));
                    if ((len > 0)) {
                        (self->cur += len);
                    } else {
                        (self->cur++);
                    }
                }
            }
        }
        if ((! terminated)) {
            Lexer_reportErrorCode(self, ErrorCode_LexUnterminatedChar, self->bufStart, self->bufEnd, start, "unterminated character literal");
        }
        return Lexer_makeToken(self, TokenKind_CharLit, start);
    }
    Token op = Lexer_lexOperator(self, c, start);
    if ((op.kind != TokenKind_Eof)) {
        return op;
    }
    Lexer_reportErrorCode(self, ErrorCode_LexUnknownChar, self->bufStart, self->bufEnd, start, "unknown character");
    return Lexer_makeToken(self, TokenKind_Unknown, start);
}



