enum TypeKind_tag {
    TypeKind_Error = 0,
    TypeKind_Void,
    TypeKind_Bool,
    TypeKind_Char,
    TypeKind_I8,
    TypeKind_U8,
    TypeKind_I16,
    TypeKind_U16,
    TypeKind_I32,
    TypeKind_U32,
    TypeKind_I64,
    TypeKind_U64,
    TypeKind_I128,
    TypeKind_U128,
    TypeKind_F32,
    TypeKind_F64,
    TypeKind_Isize,
    TypeKind_Usize,
    TypeKind_Rawptr,
    TypeKind_Str,
    TypeKind_Named,
    TypeKind_Pointer,
    TypeKind_Const,
    TypeKind_Comptime,
    TypeKind_Slice,
    TypeKind_Array,
    TypeKind_FnPtr,
    TypeKind_Tuple,
    TypeKind_TypeParam
};

typedef struct TypeKind {
    enum TypeKind_tag tag;
    union {
        struct {
            Str name;
            Ty* genericArgs;
            uint32_t genericArgsLen;
        } Named;
        struct {
            Ty base;
        } Pointer;
        struct {
            Ty base;
        } Const;
        struct {
            Ty base;
        } Comptime;
        struct {
            Ty base;
        } Slice;
        struct {
            Ty base;
            uint32_t len;
        } Array;
        struct {
            Ty returnType;
            Ty* params;
            uint32_t paramsLen;
            Str name;
        } FnPtr;
        struct {
            Ty* elems;
            uint32_t elemsLen;
        } Tuple;
        struct {
            Str name;
            uint32_t index;
        } TypeParam;
    } payload;
} TypeKind;

typedef struct TypeEntry {
    TypeKind kind;
    SourceLoc loc;
} TypeEntry;




