enum PatKind_tag {
    PatKind_Wildcard = 0,
    PatKind_Lit,
    PatKind_Ident,
    PatKind_Type,
    PatKind_Variant,
    PatKind_Tuple,
    PatKind_Struct,
    PatKind_Or,
    PatKind_Guard,
    PatKind_Range
};

typedef struct PatKind {
    enum PatKind_tag tag;
    union {
        struct {
            NodeId expr;
        } Lit;
        struct {
            Str name;
        } Ident;
        struct {
            Ty typeNode;
        } Type;
        struct {
            Str typeName;
            Str variantName;
            Str* fieldNames;
            uint32_t fieldNamesLen;
        } Variant;
        struct {
            NodeId* elems;
            uint32_t elemsLen;
        } Tuple;
        struct {
            Str name;
            Str* fieldNames;
            uint32_t fieldNamesLen;
        } Struct;
        struct {
            NodeId* alternatives;
            uint32_t alternativesLen;
        } Or;
        struct {
            NodeId pattern;
            NodeId cond;
        } Guard;
        struct {
            NodeId start;
            NodeId end;
            uint8_t flags;
        } Range;
    } payload;
} PatKind;

typedef struct Pat {
    PatKind kind;
    SourceLoc loc;
} Pat;




