enum DeclKind_tag {
    DeclKind_Import = 0,
    DeclKind_ModReexport,
    DeclKind_Struct,
    DeclKind_Enum,
    DeclKind_Variant,
    DeclKind_Union,
    DeclKind_Trait,
    DeclKind_Extend,
    DeclKind_ExtendTrait,
    DeclKind_Func,
    DeclKind_Constant,
    DeclKind_TypeAlias,
    DeclKind_Distinct,
    DeclKind_Flag,
    DeclKind_Comptime
};

typedef struct DeclKind {
    enum DeclKind_tag tag;
    union {
        struct {
            Str path;
            ImportSymbol* symbols;
            uint32_t symbolsLen;
            uint8_t flags;
        } Import;
        struct {
            Str alias;
            Str path;
            ImportSymbol* symbols;
            uint32_t symbolsLen;
            uint8_t flags;
        } ModReexport;
        struct {
            Str name;
            NodeId* genericParams;
            uint32_t genericParamsLen;
            NodeId* fields;
            uint32_t fieldsLen;
            NodeId* methods;
            uint32_t methodsLen;
            uint8_t flags;
        } Struct;
        struct {
            Str name;
            Ty backingType;
            NodeId* variants;
            uint32_t variantsLen;
            uint8_t flags;
        } Enum;
        struct {
            Str name;
            NodeId* genericParams;
            uint32_t genericParamsLen;
            VariantVariant* variants;
            uint32_t variantsLen;
            NodeId* methods;
            uint32_t methodsLen;
            uint8_t flags;
        } Variant;
        struct {
            Str name;
            NodeId* genericParams;
            uint32_t genericParamsLen;
            NodeId* fields;
            uint32_t fieldsLen;
            NodeId* methods;
            uint32_t methodsLen;
            uint8_t flags;
        } Union;
        struct {
            Str name;
            NodeId* genericParams;
            uint32_t genericParamsLen;
            NodeId* methods;
            uint32_t methodsLen;
            uint8_t flags;
        } Trait;
        struct {
            Ty selfType;
            NodeId* genericParams;
            uint32_t genericParamsLen;
            NodeId* methods;
            uint32_t methodsLen;
        } Extend;
        struct {
            Ty selfType;
            Str traitName;
            NodeId* genericParams;
            uint32_t genericParamsLen;
            NodeId* methods;
            uint32_t methodsLen;
        } ExtendTrait;
        struct {
            Str name;
            NodeId* genericParams;
            uint32_t genericParamsLen;
            NodeId* params;
            uint32_t paramsLen;
            Ty returnType;
            NodeId body;
            uint8_t flags;
        } Func;
        struct {
            Str name;
            Ty typeNode;
            NodeId value;
            uint8_t flags;
        } Constant;
        struct {
            Str name;
            Ty target;
            uint8_t flags;
        } TypeAlias;
        struct {
            Str name;
            Ty baseType;
            uint8_t flags;
        } Distinct;
        struct {
            Str flagName;
            NodeId* branches;
            uint32_t branchesLen;
        } Flag;
        struct {
            NodeId* decls;
            uint32_t declsLen;
        } Comptime;
    } payload;
} DeclKind;

