enum StmtKind_tag {
    StmtKind_ExprStmt = 0,
    StmtKind_VarDecl,
    StmtKind_Assign,
    StmtKind_Return,
    StmtKind_Break,
    StmtKind_Continue,
    StmtKind_Block,
    StmtKind_If,
    StmtKind_While,
    StmtKind_Loop,
    StmtKind_For,
    StmtKind_ForIn,
    StmtKind_Switch,
    StmtKind_Defer,
    StmtKind_Comptime,
    StmtKind_Asm
};

typedef struct StmtKind {
    enum StmtKind_tag tag;
    union {
        struct {
            NodeId expr;
        } ExprStmt;
        struct {
            Str name;
            Ty typeNode;
            NodeId init;
            uint8_t flags;
        } VarDecl;
        struct {
            NodeId target;
            NodeId value;
            Str op;
        } Assign;
        struct {
            NodeId value;
        } Return;
        struct {
            NodeId* stmts;
            uint32_t stmtsLen;
        } Block;
        struct {
            NodeId cond;
            NodeId thenBody;
            NodeId elseBody;
        } If;
        struct {
            NodeId cond;
            NodeId body;
        } While;
        struct {
            NodeId body;
        } Loop;
        struct {
            NodeId init;
            NodeId cond;
            NodeId post;
            NodeId body;
            uint8_t flags;
        } For;
        struct {
            Str bindName;
            Ty bindType;
            NodeId iterExpr;
            NodeId body;
            uint8_t flags;
        } ForIn;
        struct {
            NodeId expr;
            SwitchCase* cases;
            uint32_t casesLen;
        } Switch;
        struct {
            NodeId stmt;
        } Defer;
        struct {
            NodeId* stmts;
            uint32_t stmtsLen;
        } Comptime;
        struct {
            NodeId* template;
            uint32_t templateLen;
            NodeId* outputs;
            uint32_t outputsLen;
            NodeId* inputs;
            uint32_t inputsLen;
            NodeId* clobbers;
            uint32_t clobbersLen;
            uint8_t flags;
        } Asm;
    } payload;
} StmtKind;

typedef struct Stmt {
    StmtKind kind;
    SourceLoc loc;
    Attribute* attrs;
    uint32_t attrsLen;
} Stmt;




