NodeId Parser_parseFlagStmt(Parser* self) {
    Parser_advance(self);
    Parser_expect(self, TokenKind_LParen);
    Token tknn = Parser_expect(self, TokenKind_Ident);
    Str nameStr = AstContext_intern(self->ctx, tknn.data.ptr, tknn.data.len);
    Parser_expect(self, TokenKind_RParen);
    Parser_expect(self, TokenKind_LBrace);
    NodeId chosenNodeId = Parser_noneNode(self);
    NodeId elseNodeId = Parser_noneNode(self);
    while (((! Parser_atEnd(self)) && (self->current.kind != TokenKind_RBrace))) {
        _Bool isElse = 0;
        Str keyStr = 0;
        if (Parser_match(self, TokenKind_Else)) {
            (isElse = 1);
        } else {
            {
                Token ky = Parser_expect(self, TokenKind_Ident);
                (keyStr = AstContext_intern(self->ctx, ky.data.ptr, ky.data.len));
            }
        }
        Parser_expect(self, TokenKind_FatArrow);
        NodeId bl = Parser_noneNode(self);
        if (Parser_match(self, TokenKind_LBrace)) {
            NodeListBuilder stl;
            AstContext_nodeListInit(self->ctx, (& stl));
            while (((! Parser_atEnd(self)) && (self->current.kind != TokenKind_RBrace))) {
                NodeId st = Parser_parseStmt(self);
                if ((! AstContext_nodeListAppend(self->ctx, (& stl), st))) {
                    Parser_reportAllocFailed(self);
                }
            }
            Parser_expect(self, TokenKind_RBrace);
            uint32_t countIdx = stl.len;
            NodeId* vals = AstContext_nodeListFinish(self->ctx, (& stl));
            (bl = Parser_storeStmt(self, (StmtKind){ .tag = StmtKind_Block, .payload.Block = {.stmts = vals, .stmtsLen = countIdx} }));
        } else {
            {
                (bl = Parser_parseStmt(self));
            }
        }
        if (isElse) {
            (elseNodeId = bl);
        } else {
            {
                Str flagValStr = 0;
                uint32_t ii = 0;
                while ((ii < self->ctx->flagsLen)) {
                    if ((self->ctx->flagNames[ii] == nameStr)) {
                        (flagValStr = self->ctx->flagValues[ii]);
                        break;
                    }
                    (ii = (ii + 1));
                }
                if (((flagValStr != 0) && (flagValStr == keyStr))) {
                    (chosenNodeId = bl);
                }
            }
        }
        if ((! Parser_match(self, TokenKind_Comma))) {
            break;
        }
    }
    Parser_expect(self, TokenKind_RBrace);
    if ((chosenNodeId.index != 0)) {
        return chosenNodeId;
    }
    if ((elseNodeId.index != 0)) {
        return elseNodeId;
    }
    Parser_reportCurrentError(self, ErrorCode_ParseExpectedStmt, "no arm of this flag statement matched; add an `else` arm");
    return Parser_noneNode(self);
}
