    NodeId* values = AstContext_nodeListFinish(self->ctx, (& template));
    uint32_t outputsLen = outputs.len;
    NodeId* outputsItems = AstContext_nodeListFinish(self->ctx, (& outputs));
    uint32_t inputsLen = inputs.len;
    NodeId* inputsItems = AstContext_nodeListFinish(self->ctx, (& inputs));
    uint32_t clobbersLen = clobbers.len;
    NodeId* clobbersItems = AstContext_nodeListFinish(self->ctx, (& clobbers));
    return Parser_storeStmt(self, (StmtKind){ .tag = StmtKind_Asm, .payload.Asm = {.template = values, .templateLen = count, .outputs = outputsItems, .outputsLen = outputsLen, .inputs = inputsItems, .inputsLen = inputsLen, .clobbers = clobbersItems, .clobbersLen = clobbersLen, .flags = flags} });
