        if ((self->current.kind == TokenKind_Const)) {
            Parser_advance(self);
            (isConst = 1);
        } else {
            if ((self->current.kind == TokenKind_Static)) {
                Parser_advance(self);
                (isStatic = 1);
            } else {
                Parser_advance(self);
            }
        }
        Ty typeNode = 0;
        if (Parser_isTypeStart(self)) {
            ParserMark mark = Parser_save(self);
            Ty candidate = Parser_parseType(self);
            if ((self->current.kind == TokenKind_Ident)) {
                (typeNode = candidate);
                Parser_endSpeculation(self);
            } else {
                {
                    Parser_restore(self, mark);
                }
            }
        }
        Token name = Parser_expectName(self);
        if ((typeNode != 0)) {
            (typeNode = Parser_parseDeclaratorArray(self, typeNode));
        }
        Str nameId = AstContext_intern(self->ctx, name.data.ptr, name.data.len);
        NodeId init = Parser_noneNode(self);
        if (isStatic) {
            if (Parser_match(self, TokenKind_Equal)) {
                (init = Parser_parseInitExpr(self));
            }
        } else {
            {
                Parser_expect(self, TokenKind_Equal);
                (init = Parser_parseInitExpr(self));
            }
        }
        (typeNode = Parser_inferArrayFromInit(self, typeNode, init));
        Parser_expect(self, TokenKind_Semicolon);
        uint8_t flags = 0;
        if ((init.index != 0)) {
            (flags = (flags | 2));
        }
