void Parser_rebindTypeParams(Parser* self, Ty ty, NodeId* genericValues, uint32_t genericCount) {
    if (((ty == 0) || (genericCount == 0))) {
        return;
    }
    TypeEntry* entry = (self->ctx->types + ty);
    if ((entry->kind.tag == TypeKind_Named)) {
        Str nm = entry->kind.payload.Named.name;
        uint32_t g = 0;
        while ((g < genericCount)) {
            Node* gn = (self->ctx->nodes + genericValues[g].index);
            if ((gn->kind.tag == NodeKind_GenericParam)) {
                if ((gn->kind.payload.GenericParam.value.name == nm)) {
                    (entry->kind = (TypeKind){ .tag = TypeKind_TypeParam, .payload.TypeParam = {.name = nm, .index = g} });
                    return;
                }
            }
            (g = (g + 1));
        }
        uint32_t i = 0;
        while ((i < entry->kind.payload.Named.genericArgsLen)) {
            Parser_rebindTypeParams(self, entry->kind.payload.Named.genericArgs[i], genericValues, genericCount);
            (i = (i + 1));
        }
        return;
    }
    if ((entry->kind.tag == TypeKind_Pointer)) {
        Parser_rebindTypeParams(self, entry->kind.payload.Pointer.base, genericValues, genericCount);
        return;
    }
    if ((entry->kind.tag == TypeKind_Const)) {
        Parser_rebindTypeParams(self, entry->kind.payload.Const.base, genericValues, genericCount);
        return;
    }
    if ((entry->kind.tag == TypeKind_Comptime)) {
        Parser_rebindTypeParams(self, entry->kind.payload.Comptime.base, genericValues, genericCount);
        return;
    }
    if ((entry->kind.tag == TypeKind_Slice)) {
        Parser_rebindTypeParams(self, entry->kind.payload.Slice.base, genericValues, genericCount);
        return;
    }
    if ((entry->kind.tag == TypeKind_Array)) {
        Parser_rebindTypeParams(self, entry->kind.payload.Array.base, genericValues, genericCount);
        return;
    }
    if ((entry->kind.tag == TypeKind_FnPtr)) {
        Parser_rebindTypeParams(self, entry->kind.payload.FnPtr.returnType, genericValues, genericCount);
        uint32_t p = 0;
        while ((p < entry->kind.payload.FnPtr.paramsLen)) {
            Parser_rebindTypeParams(self, entry->kind.payload.FnPtr.params[p], genericValues, genericCount);
            (p = (p + 1));
        }
        return;
    }
    if ((entry->kind.tag == TypeKind_Tuple)) {
        uint32_t e = 0;
        while ((e < entry->kind.payload.Tuple.elemsLen)) {
            Parser_rebindTypeParams(self, entry->kind.payload.Tuple.elems[e], genericValues, genericCount);
            (e = (e + 1));
        }
        return;
    }
}
NodeId Parser_parseFuncOrVarDecl(Parser* self, _Bool isPub, _Bool isExtern, _Bool isStatic, _Bool isConst) {
    Ty retType = Parser_parseType(self);
    if (Parser_match(self, TokenKind_Const)) {
        (isConst = 1);
    }
    Token nameTok = Parser_expectName(self);
    Str name = AstContext_intern(self->ctx, nameTok.data.ptr, nameTok.data.len);
    NodeListBuilder genericParams;
    AstContext_nodeListInit(self->ctx, (& genericParams));
    if ((self->current.kind == TokenKind_Less)) {
        Parser_parseGenericParams(self, (& genericParams));
    }
    uint32_t genericCount = genericParams.len;
    NodeId* genericValues = AstContext_nodeListFinish(self->ctx, (& genericParams));
    Parser_rebindTypeParams(self, retType, genericValues, genericCount);
    Parser_rebindTypeParams(self, retType, self->outerGenerics, self->outerGenericsLen);
    uint8_t flags = 0;
    if (isPub) {
        (flags = (flags | 1));
    }
    if (isExtern) {
        (flags = (flags | 2));
    }
    if (isStatic) {
        (flags = (flags | 4));
    }
    if (isConst) {
        (flags = (flags | 16));
    }
    if ((self->current.kind == TokenKind_LParen)) {
        Parser_advance(self);
        NodeListBuilder params;
        AstContext_nodeListInit(self->ctx, (& params));
        if ((self->current.kind != TokenKind_RParen)) {
            NodeId param = Parser_parseParam(self);
            if ((! AstContext_nodeListAppend(self->ctx, (& params), param))) {
                Parser_reportAllocFailed(self);
            }
            while (Parser_match(self, TokenKind_Comma)) {
                (param = Parser_parseParam(self));
                if ((! AstContext_nodeListAppend(self->ctx, (& params), param))) {
                    Parser_reportAllocFailed(self);
                }
            }
        }
        Parser_expect(self, TokenKind_RParen);
        if (Parser_match(self, TokenKind_Const)) {
            (flags = (flags | 16));
        }
        uint32_t paramCount = params.len;
        NodeId* paramValues = AstContext_nodeListFinish(self->ctx, (& params));
        uint32_t pi = 0;
        while ((pi < paramCount)) {
            Node* pn = (self->ctx->nodes + paramValues[pi].index);
            if ((pn->kind.tag == NodeKind_Param)) {
                Parser_rebindTypeParams(self, pn->kind.payload.Param.value.typeNode, genericValues, genericCount);
                Parser_rebindTypeParams(self, pn->kind.payload.Param.value.typeNode, self->outerGenerics, self->outerGenericsLen);
            }
            (pi = (pi + 1));
        }
        NodeId body = Parser_noneNode(self);
        if ((! Parser_match(self, TokenKind_Semicolon))) {
            (body = Parser_parseBlock(self));
            (flags = (flags | 8));
        }
        return Parser_storeDecl(self, (DeclKind){ .tag = DeclKind_Func, .payload.Func = {.name = name, .genericParams = genericValues, .genericParamsLen = genericCount, .params = paramValues, .paramsLen = paramCount, .returnType = retType, .body = body, .flags = flags} });
    }
    NodeId value = Parser_noneNode(self);
    Ty varType = Parser_parseDeclaratorArray(self, retType);
    if (Parser_match(self, TokenKind_Equal)) {
        (value = Parser_parseInitExpr(self));
        Parser_expect(self, TokenKind_Semicolon);
    } else {
        {
            Parser_expect(self, TokenKind_Semicolon);
        }
    }
    (varType = Parser_inferArrayFromInit(self, varType, value));
    return Parser_storeDecl(self, (DeclKind){ .tag = DeclKind_Constant, .payload.Constant = {.name = name, .typeNode = varType, .value = value, .flags = flags} });
}
NodeId Parser_parseGenericParam(Parser* self) {
    GenericParam param;
    (param.bounds = NULL);
    (param.boundsLen = 0);
    (param.flags = 0);
    if (Parser_match(self, TokenKind_Comptime)) {
        (param.flags = (param.flags | 1));
    }
    Token nameTok = Parser_expectName(self);
    (param.name = AstContext_intern(self->ctx, nameTok.data.ptr, nameTok.data.len));
    return Parser_storeNode(self, (NodeKind){ .tag = NodeKind_GenericParam, .payload.GenericParam = {.value = param} });
}
void Parser_parseGenericParams(Parser* self, NodeListBuilder* params) {
    Parser_expect(self, TokenKind_Less);
    if (Parser_consumeGreater(self)) {
        return;
    }
    while (1) {
        NodeId param = Parser_parseGenericParam(self);
        if ((! AstContext_nodeListAppend(self->ctx, params, param))) {
            Parser_reportAllocFailed(self);
        }
        if ((! Parser_match(self, TokenKind_Comma))) {
            break;
        }
    }
    if ((! Parser_consumeGreater(self))) {
        Parser_reportCurrentError(self, ErrorCode_ParseExpectedToken, "expected '>' to close generic parameters");
    }
}
NodeId Parser_parseFuncDecl(Parser* self) {
    return Parser_parseFuncDeclFlags(self, 0);
}
NodeId Parser_parseFuncDeclFlags(Parser* self, uint8_t attrFlags) {
    (attrFlags = (attrFlags | Parser_parseAttrList(self)));
    _Bool isConst = ((attrFlags & 1) != 0);
    return Parser_parseFuncOrVarDecl(self, 0, 0, 0, isConst);
}
NodeId Parser_parseParam(Parser* self) {
    Param param;
    (param.loc.data = 0);
    (param.flags = 0);
    if ((self->current.kind == TokenKind_Self)) {
        Parser_advance(self);
        (param.name = AstContext_intern(self->ctx, "self", 4));
        (param.typeNode = 0);
        (param.flags = 1);
        return Parser_storeParam(self, param);
    }
    if ((self->current.kind == TokenKind_Ellipsis)) {
        Parser_advance(self);
        (param.name = 0);
        (param.typeNode = 0);
        (param.flags = 16);
        if ((self->current.kind == TokenKind_Ident)) {
            Token varTok = Parser_advance(self);
            (param.name = AstContext_intern(self->ctx, varTok.data.ptr, varTok.data.len));
        }
        return Parser_storeParam(self, param);
    }
    (param.typeNode = Parser_parseType(self));
    {
        Ty resolved = param.typeNode;
        TypeEntry* typeEntry = ((resolved != 0) ? (self->ctx->types + resolved) : NULL);
        while (((typeEntry != NULL) && ((typeEntry->kind.tag == TypeKind_Const) || (typeEntry->kind.tag == TypeKind_Pointer)))) {
            if ((typeEntry->kind.tag == TypeKind_Const)) {
                (resolved = typeEntry->kind.payload.Const.base);
            } else {
                (resolved = typeEntry->kind.payload.Pointer.base);
            }
            if ((resolved == 0)) {
                break;
            }
            (typeEntry = (self->ctx->types + resolved));
        }
        if ((((typeEntry != NULL) && (typeEntry->kind.tag == TypeKind_Named)) && (typeEntry->kind.payload.Named.name == AstContext_intern(self->ctx, ((uint8_t*)"self"), 4)))) {
            (param.name = AstContext_intern(self->ctx, ((uint8_t*)"self"), 4));
            (param.flags = 1);
            return Parser_storeParam(self, param);
        }
    }
    if (((self->current.kind == TokenKind_Comma) || (self->current.kind == TokenKind_RParen))) {
        (param.name = 0);
        (param.flags = 8);
        if ((param.typeNode != 0)) {
            Ty resolved = param.typeNode;
            TypeEntry* typeEntry = (self->ctx->types + resolved);
            while (((typeEntry != NULL) && (typeEntry->kind.tag == TypeKind_Const))) {
                (resolved = typeEntry->kind.payload.Const.base);
                if ((resolved == 0)) {
                    break;
                }
                (typeEntry = (self->ctx->types + resolved));
            }
            if (((typeEntry != NULL) && (typeEntry->kind.tag == TypeKind_Comptime))) {
                Ty base = typeEntry->kind.payload.Comptime.base;
                (typeEntry = ((base != 0) ? (self->ctx->types + base) : NULL));
            }
            if (((typeEntry != NULL) && (typeEntry->kind.tag == TypeKind_Named))) {
                (param.name = typeEntry->kind.payload.Named.name);
            }
        }
        return Parser_storeParam(self, param);
    }
    Token name = Parser_expectName(self);
    (param.name = AstContext_intern(self->ctx, name.data.ptr, name.data.len));
    if ((param.typeNode != 0)) {
        (param.typeNode = Parser_parseDeclaratorArray(self, param.typeNode));
    }
    return Parser_storeParam(self, param);
}
NodeId Parser_parseStructDecl(Parser* self, _Bool isPub) {
    Parser_expect(self, TokenKind_Struct);
    Token nameTok = Parser_expect(self, TokenKind_Ident);
    Str name = AstContext_intern(self->ctx, nameTok.data.ptr, nameTok.data.len);
    NodeListBuilder genericParams;
    AstContext_nodeListInit(self->ctx, (& genericParams));
    if ((self->current.kind == TokenKind_Less)) {
        Parser_parseGenericParams(self, (& genericParams));
    }
    uint32_t genericCount = genericParams.len;
    NodeId* genericValues = AstContext_nodeListFinish(self->ctx, (& genericParams));
    (self->outerGenerics = genericValues);
    (self->outerGenericsLen = genericCount);
    NodeListBuilder fields;
    NodeListBuilder methods;
    AstContext_nodeListInit(self->ctx, (& fields));
    AstContext_nodeListInit(self->ctx, (& methods));
    Parser_expect(self, TokenKind_LBrace);
    while (((self->current.kind != TokenKind_RBrace) && (! Parser_atEnd(self)))) {
        uint8_t memberAttrs = Parser_parseAttrList(self);
        uint8_t fieldFlags = 0;
        if (Parser_match(self, TokenKind_Pub)) {
            (fieldFlags = 1);
        }
        if (((self->current.kind == TokenKind_Extern) || (self->current.kind == TokenKind_Static))) {
            _Bool mIsExtern = Parser_match(self, TokenKind_Extern);
            if ((mIsExtern && (self->current.kind == TokenKind_LParen))) {
                Parser_advance(self);
                Parser_expect(self, TokenKind_String);
                Parser_expect(self, TokenKind_RParen);
            }
            _Bool mIsStatic = Parser_match(self, TokenKind_Static);
            NodeId method = Parser_parseFuncOrVarDecl(self, (fieldFlags == 1), mIsExtern, mIsStatic, ((memberAttrs & 1) != 0));
            if ((! AstContext_nodeListAppend(self->ctx, (& methods), method))) {
                Parser_reportAllocFailed(self);
            }
            Parser_match(self, TokenKind_Semicolon);
            continue;
        }
        ParserMark mark = Parser_save(self);
        Parser_parseType(self);
        Parser_expect(self, TokenKind_Ident);
        _Bool isMethod = ((self->current.kind == TokenKind_LParen) || (self->current.kind == TokenKind_Less));
        Parser_restore(self, mark);
        if (isMethod) {
            NodeId method = Parser_parseFuncDeclFlags(self, memberAttrs);
            if ((! AstContext_nodeListAppend(self->ctx, (& methods), method))) {
                Parser_reportAllocFailed(self);
            }
            Parser_match(self, TokenKind_Semicolon);
            continue;
        }
        Ty fieldType = Parser_parseType(self);
        while (1) {
            Token fieldNameTok = Parser_expect(self, TokenKind_Ident);
            Ty declType = Parser_parseDeclaratorArray(self, fieldType);
            Field field;
            (field.name = AstContext_intern(self->ctx, fieldNameTok.data.ptr, fieldNameTok.data.len));
            (field.typeNode = declType);
            (field.defaultValue = Parser_noneNode(self));
            (field.loc.data = 0);
            (field.flags = fieldFlags);
            if (Parser_match(self, TokenKind_Equal)) {
                (field.defaultValue = Parser_parseExpr(self));
                (field.flags = (field.flags | 2));
            }
            NodeId fieldNode = Parser_storeField(self, field);
            if ((! AstContext_nodeListAppend(self->ctx, (& fields), fieldNode))) {
                Parser_reportAllocFailed(self);
            }
            if ((! Parser_match(self, TokenKind_Comma))) {
                break;
            }
        }
        Parser_match(self, TokenKind_Semicolon);
    }
    Parser_expect(self, TokenKind_RBrace);
    (self->outerGenerics = NULL);
    (self->outerGenericsLen = 0);
    uint32_t fieldCount = fields.len;
    NodeId* fieldValues = AstContext_nodeListFinish(self->ctx, (& fields));
    uint32_t methodCount = methods.len;
    NodeId* methodValues = AstContext_nodeListFinish(self->ctx, (& methods));
    uint8_t flags = 0;
    if (isPub) {
        (flags = 1);
    }
    return Parser_storeDecl(self, (DeclKind){ .tag = DeclKind_Struct, .payload.Struct = {.name = name, .genericParams = genericValues, .genericParamsLen = genericCount, .fields = fieldValues, .fieldsLen = fieldCount, .methods = methodValues, .methodsLen = methodCount, .flags = flags} });
}
NodeId Parser_parseEnumDecl(Parser* self, _Bool isPub) {
    Parser_expect(self, TokenKind_Enum);
    Token nameTok = Parser_expect(self, TokenKind_Ident);
    Str name = AstContext_intern(self->ctx, nameTok.data.ptr, nameTok.data.len);
    Ty backingType = 0;
    uint8_t flags = 0;
    if (Parser_match(self, TokenKind_Colon)) {
        (backingType = Parser_parseType(self));
        (flags = 1);
    }
    if (isPub) {
        (flags = (flags | 2));
    }
    NodeListBuilder variants;
    AstContext_nodeListInit(self->ctx, (& variants));
    Parser_expect(self, TokenKind_LBrace);
    if ((self->current.kind != TokenKind_RBrace)) {
        while (1) {
            EnumVariant enumValue;
            Token variantTok = Parser_expect(self, TokenKind_Ident);
            (enumValue.name = AstContext_intern(self->ctx, variantTok.data.ptr, variantTok.data.len));
            (enumValue.value = Parser_noneNode(self));
            (enumValue.loc.data = 0);
            (enumValue.flags = 0);
            if (Parser_match(self, TokenKind_Equal)) {
                (enumValue.value = Parser_parseExpr(self));
                (enumValue.flags = 1);
            }
            NodeId variantNode = Parser_storeNode(self, (NodeKind){ .tag = NodeKind_EnumVariant, .payload.EnumVariant = {.value = enumValue} });
            if ((! AstContext_nodeListAppend(self->ctx, (& variants), variantNode))) {
                Parser_reportAllocFailed(self);
            }
            if ((! Parser_match(self, TokenKind_Comma))) {
                break;
            }
            if ((self->current.kind == TokenKind_RBrace)) {
                break;
            }
        }
    }
    Parser_expect(self, TokenKind_RBrace);
    uint32_t variantCount = variants.len;
    NodeId* variantValues = AstContext_nodeListFinish(self->ctx, (& variants));
    return Parser_storeDecl(self, (DeclKind){ .tag = DeclKind_Enum, .payload.Enum = {.name = name, .backingType = backingType, .variants = variantValues, .variantsLen = variantCount, .flags = flags} });
}
NodeId Parser_parseVariantDecl(Parser* self, _Bool isPub) {
    Parser_expect(self, TokenKind_Variant);
    Token nameTok = Parser_expect(self, TokenKind_Ident);
    Str name = AstContext_intern(self->ctx, nameTok.data.ptr, nameTok.data.len);
    NodeListBuilder genericParams;
    AstContext_nodeListInit(self->ctx, (& genericParams));
    if ((self->current.kind == TokenKind_Less)) {
        Parser_parseGenericParams(self, (& genericParams));
    }
    uint32_t genericCount = genericParams.len;
    NodeId* genericValues = AstContext_nodeListFinish(self->ctx, (& genericParams));
    (self->outerGenerics = genericValues);
    (self->outerGenericsLen = genericCount);
    VariantListBuilder variants;
    NodeListBuilder methods;
    AstContext_variantListInit(self->ctx, (& variants));
    AstContext_nodeListInit(self->ctx, (& methods));
    Parser_expect(self, TokenKind_LBrace);
    while (((self->current.kind != TokenKind_RBrace) && (! Parser_atEnd(self)))) {
        if ((self->current.kind == TokenKind_Pub)) {
            Parser_advance(self);
            NodeId method = Parser_parseFuncDecl(self);
            if ((! AstContext_nodeListAppend(self->ctx, (& methods), method))) {
                Parser_reportAllocFailed(self);
            }
            continue;
        }
        Token variantTok = Parser_expect(self, TokenKind_Ident);
        VariantVariant variantValue;
        (variantValue.name = AstContext_intern(self->ctx, variantTok.data.ptr, variantTok.data.len));
        (variantValue.fieldNames = NULL);
        (variantValue.fieldTypes = NULL);
        (variantValue.fieldsLen = 0);
        (variantValue.loc.data = 0);
        if ((self->current.kind == TokenKind_LBrace)) {
            Parser_advance(self);
            StrListBuilder fieldNames;
            TyListBuilder fieldTypes;
            AstContext_strListInit(self->ctx, (& fieldNames));
            AstContext_tyListInit(self->ctx, (& fieldTypes));
            while (((self->current.kind != TokenKind_RBrace) && (! Parser_atEnd(self)))) {
                Ty fieldType = Parser_parseType(self);
                Token fieldTok = Parser_expect(self, TokenKind_Ident);
                Str fieldName = AstContext_intern(self->ctx, fieldTok.data.ptr, fieldTok.data.len);
                if ((! AstContext_tyListAppend(self->ctx, (& fieldTypes), fieldType))) {
                    Parser_reportAllocFailed(self);
                }
                if ((! AstContext_strListAppend(self->ctx, (& fieldNames), fieldName))) {
                    Parser_reportAllocFailed(self);
                }
                if (((! Parser_match(self, TokenKind_Comma)) && (! Parser_match(self, TokenKind_Semicolon)))) {
                    break;
                }
            }
            Parser_expect(self, TokenKind_RBrace);
            (variantValue.fieldsLen = fieldNames.len);
            (variantValue.fieldNames = AstContext_strListFinish(self->ctx, (& fieldNames)));
            (variantValue.fieldTypes = AstContext_tyListFinish(self->ctx, (& fieldTypes)));
        }
        if ((! AstContext_variantListAppend(self->ctx, (& variants), variantValue))) {
            Parser_reportAllocFailed(self);
        }
        Parser_match(self, TokenKind_Comma);
    }
    Parser_expect(self, TokenKind_RBrace);
    (self->outerGenerics = NULL);
    (self->outerGenericsLen = 0);
    uint32_t variantCount = variants.len;
    VariantVariant* variantValues = AstContext_variantListFinish(self->ctx, (& variants));
    uint32_t methodCount = methods.len;
    NodeId* methodValues = AstContext_nodeListFinish(self->ctx, (& methods));
    uint8_t flags = 0;
    if (isPub) {
        (flags = 1);
    }
    return Parser_storeDecl(self, (DeclKind){ .tag = DeclKind_Variant, .payload.Variant = {.name = name, .genericParams = genericValues, .genericParamsLen = genericCount, .variants = variantValues, .variantsLen = variantCount, .methods = methodValues, .methodsLen = methodCount, .flags = flags} });
}
