MemberInfo Sema_findMemberByIndex(Sema* self, Ty receiver, uint32_t index) {
    MemberInfo none;
    (none.typeNode = 0);
    (none.declaration.index = 0);
    (none.kind = 0);
    (receiver = Sema_stripType(self, receiver));
    if ((receiver == 0)) {
        return none;
    }
    TypeEntry* typeEntry = (self->ctx->types + receiver);
    if ((typeEntry->kind.tag == TypeKind_Str)) {
        if ((index == 0)) {
            (none.typeNode = Sema_strPtrType(self));
            (none.kind = 1);
            return none;
        }
        if ((index == 1)) {
            (none.typeNode = Sema_usizeType(self));
            (none.kind = 1);
            return none;
        }
        return none;
    }
    if ((typeEntry->kind.tag != TypeKind_Named)) {
        return none;
    }
    Symbol* symbol = Sema_lookupType(self, typeEntry->kind.payload.Named.name, typeEntry->loc);
    if ((symbol == NULL)) {
        return none;
    }
    Node* declNode = (self->ctx->nodes + symbol->declaration.index);
    if ((declNode->kind.tag != NodeKind_Decl)) {
        return none;
    }
    Decl* decl = (& declNode->kind.payload.Decl.value);
    NodeId* fields = NULL;
    uint32_t fieldCount = 0;
    if ((decl->kind.tag == DeclKind_Struct)) {
        (fields = decl->kind.payload.Struct.fields);
        (fieldCount = decl->kind.payload.Struct.fieldsLen);
    } else {
        if ((decl->kind.tag == DeclKind_Union)) {
            (fields = decl->kind.payload.Union.fields);
            (fieldCount = decl->kind.payload.Union.fieldsLen);
        }
    }
    if (((fields == NULL) || (index >= fieldCount))) {
        return none;
    }
    Node* fieldNode = (self->ctx->nodes + fields[index].index);
    if ((fieldNode->kind.tag != NodeKind_Field)) {
        return none;
    }
    (none.typeNode = fieldNode->kind.payload.Field.value.typeNode);
    (none.declaration = fields[index]);
    (none.kind = 1);
    return none;
}
MemberInfo Sema_findMethod(Sema* self, Ty receiver, Str name) {
    MemberInfo none;
    (none.typeNode = 0);
    (none.declaration.index = 0);
    (none.kind = 0);
    (receiver = Sema_stripType(self, receiver));
    if ((receiver == 0)) {
        return none;
    }
    TypeEntry* typeEntry = (self->ctx->types + receiver);
    if (((typeEntry->kind.tag != TypeKind_Named) && (typeEntry->kind.tag != TypeKind_Str))) {
        return none;
    }
    if ((typeEntry->kind.tag == TypeKind_Named)) {
        Symbol* symbol = Sema_lookupType(self, typeEntry->kind.payload.Named.name, typeEntry->loc);
        if ((symbol == NULL)) {
            return none;
        }
        Node* declNode = (self->ctx->nodes + symbol->declaration.index);
        if ((declNode->kind.tag != NodeKind_Decl)) {
            return none;
        }
        Decl* decl = (& declNode->kind.payload.Decl.value);
        NodeId* methods = NULL;
        uint32_t methodCount = 0;
        switch (decl->kind.tag) {
            case DeclKind_Struct:
            {
                (methods = decl->kind.payload.Struct.methods);
                (methodCount = decl->kind.payload.Struct.methodsLen);
                break;
            }
            case DeclKind_Union:
            {
                (methods = decl->kind.payload.Union.methods);
                (methodCount = decl->kind.payload.Union.methodsLen);
                break;
            }
            case DeclKind_Trait:
            {
                (methods = decl->kind.payload.Trait.methods);
                (methodCount = decl->kind.payload.Trait.methodsLen);
                break;
            }
            case DeclKind_Variant:
            {
                (methods = decl->kind.payload.Variant.methods);
                (methodCount = decl->kind.payload.Variant.methodsLen);
                break;
            }
            default:
            {
                break;
            }
        }
        uint32_t i = 0;
        while ((i < methodCount)) {
            Node* methodNode = (self->ctx->nodes + methods[i].index);
            if ((methodNode->kind.tag == NodeKind_Decl)) {
                Decl* method = (& methodNode->kind.payload.Decl.value);
                if (((method->kind.tag == DeclKind_Func) && (method->kind.payload.Func.name == name))) {
                    (none.typeNode = method->kind.payload.Func.returnType);
                    (none.declaration = methods[i]);
                    (none.kind = 2);
                    return none;
                }
            }
            (i = (i + 1));
        }
    }
    uint32_t e = 0;
    while ((e < self->extendsLen)) {
        Node* extNode = (self->ctx->nodes + self->extends[e].index);
        if ((extNode->kind.tag == NodeKind_Decl)) {
            Decl* ext = (& extNode->kind.payload.Decl.value);
            NodeId* extMethods = NULL;
            uint32_t extMethodsLen = 0;
            _Bool matches = 0;
            if ((ext->kind.tag == DeclKind_Extend)) {
                (extMethods = ext->kind.payload.Extend.methods);
                (extMethodsLen = ext->kind.payload.Extend.methodsLen);
                if (Sema_sameTypePattern(self, ext->kind.payload.Extend.selfType, receiver)) {
                    (matches = 1);
                }
            } else {
                if ((ext->kind.tag == DeclKind_ExtendTrait)) {
                    (extMethods = ext->kind.payload.ExtendTrait.methods);
                    (extMethodsLen = ext->kind.payload.ExtendTrait.methodsLen);
                    if (Sema_sameTypePattern(self, ext->kind.payload.ExtendTrait.selfType, receiver)) {
                        (matches = 1);
                    }
                }
            }
            if (matches) {
                uint32_t m = 0;
                while ((m < extMethodsLen)) {
                    Node* methodNode = (self->ctx->nodes + extMethods[m].index);
                    if ((methodNode->kind.tag == NodeKind_Decl)) {
                        Decl* method = (& methodNode->kind.payload.Decl.value);
                        if (((method->kind.tag == DeclKind_Func) && (method->kind.payload.Func.name == name))) {
                            (none.typeNode = method->kind.payload.Func.returnType);
                            (none.declaration = extMethods[m]);
                            (none.kind = 2);
                            return none;
                        }
                    }
                    (m = (m + 1));
                }
            }
        }
        (e = (e + 1));
    }
    return none;
}



