Ty Sema_allocType(Sema* self, TypeKind kind) {
    Ty id = AstContext_allocTypeSlot(self->ctx);
    if ((id == 0)) {
        Sema_semaErrorNode(self, ErrorCode_SemaInternal, AstContext_noneNode(self->ctx), "allocTypeSlot failed (type table full)");
        return 0;
    }
    TypeEntry* entry = (self->ctx->types + id);
    (entry->kind = kind);
    (entry->loc.data = 0);
    return id;
}
Ty Sema_boolType(Sema* self) {
    uint32_t i = 1;
    while ((i < self->ctx->typesLen)) {
        if ((self->ctx->types[i].kind.tag == TypeKind_Bool)) {
            return i;
        }
        (i++);
    }
    TypeKind kind;
    (kind.tag = TypeKind_Bool);
    return Sema_allocType(self, kind);
}
